import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百七十六章 丰厚供养的祸患","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/176第一百七十六章 丰厚供养的祸患.md","filePath":"meditation/巴利文大藏经/176第一百七十六章 丰厚供养的祸患.md"}'),_={name:"meditation/巴利文大藏经/176第一百七十六章 丰厚供养的祸患.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百七十六章-丰厚供养的祸患" tabindex="-1">第一百七十六章 丰厚供养的祸患 <a class="header-anchor" href="#第一百七十六章-丰厚供养的祸患" aria-label="Permalink to &quot;第一百七十六章 丰厚供养的祸患&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应25经/沙门婆罗门经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，任何的出家人、修行人如果他们不知道对丰厚供养、舒适生活、虔诚恭敬、广大名声渴爱、热爱的滋味是什么？不知道丰厚供养、舒适生活、虔诚恭敬、广大名声的祸患是什么？不知道如何才能从丰厚供养、舒适生活、虔诚恭敬、广大名声中解脱出来？弟子们，对于如来来说他们就不是真正的修行人、出家人，他们就不是被修行团体认可的修行人，他们就不是被僧团认可的出家人。他们不明白修行和出家的真正意义，他们无法证悟解脱的果位。</p><p>以获得丰厚供养、舒适生活、虔诚恭敬、广大名声为前提条件，就会由此生起快乐、喜悦，这就是对丰厚供养、舒适生活、虔诚恭敬、广大名声渴爱、热爱的滋味。</p><p>然而丰厚的供养、舒适的生活、虔诚的恭敬、广大的名声是无法永远存在的，是无法永恒保持不变的，是随时在变化的，因为丰厚的供养、舒适的生活、虔诚的恭敬、广大的名声是随时在变化的，是无法永远存在的，是无法永恒保持不变的，所以当丰厚的供养、舒适的生活、虔诚的恭敬、广大的名声发生变化的时候，比如当丰厚的供养、舒适的生活、虔诚的恭敬、广大的名声衰败、灭尽、消失的时候就会最终导致痛苦，这就是丰厚供养、舒适生活、虔诚恭敬、广大名声的祸患。</p><p>控制降伏对丰厚供养、舒适生活、虔诚恭敬、广大名声的贪求，除灭对丰厚供养、舒适生活、虔诚恭敬、广大名声的贪爱，不对丰厚供养、舒适生活、虔诚恭敬、广大名声生起贪欲，就不会被丰厚供养、舒适生活、虔诚恭敬、广大名声束缚捆绑，就从丰厚供养、舒适生活、虔诚恭敬、广大名声中解脱了出来。</p><p>弟子们，任何的出家人、修行人如果他们明白对丰厚供养、舒适生活、虔诚恭敬、广大名声渴爱、热爱的滋味是什么？明白丰厚供养、舒适生活、虔诚恭敬、广大名声的祸患是什么？明白如何才能从丰厚供养、舒适生活、虔诚恭敬、广大名声中解脱出来？弟子们，对于如来来说他们就是真正的修行人、出家人，他们就是被修行团体认可的修行人，他们就是被僧团认可的出家人。他们明白修行和出家的真正意义，他们能够最终证悟解脱的果位。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
